document.writeln("      </div>");
document.writeln("      <div class=\"cont\" style=\"display:none;width:120px;margin-left:350px;\">");
document.writeln("      	<iframe height=\"35\"  marginheight=\"0\" src=\"/col/col4322/index.html\" frameborder=\"0\"   allowtransparency=\"allowtransparency\" marginwidth=\"0\" scrolling=\"no\"></iframe>");
document.writeln("      </div>");
