document.writeln("      	<iframe height=\"125\"  marginheight=\"0\" src=\"/col/col4323/index.html\" frameborder=\"0\"   allowtransparency=\"allowtransparency\" marginwidth=\"0\" scrolling=\"no\"></iframe>");
