document.writeln("<script type=\"text\/javascript\">");
document.writeln("(function(){");
document.writeln("");
document.writeln("	var time = null;");
document.writeln("	var list = $(\"#naavlist\");");
document.writeln("	var box = $(\"#naavbox\");");
document.writeln("	var lista = list.find(\"a\");");
document.writeln("	");
document.writeln("	for(var i=0,j=lista.length;i<j;i++){");
document.writeln("		if(lista[i].className == \"now\"){");
document.writeln("			var olda = i;");
document.writeln("		}");
document.writeln("	}");
document.writeln("	");
document.writeln("	var box_show = function(hei){");
document.writeln("		box.stop().animate({");
document.writeln("			height:hei,");
document.writeln("			opacity:1");
document.writeln("		},400);");
document.writeln("	}");
document.writeln("	");
document.writeln("	var box_hide = function(){");
document.writeln("		box.stop().animate({");
document.writeln("			height:0,");
document.writeln("			opacity:0");
document.writeln("		},400);");
document.writeln("	}");
document.writeln("	");
document.writeln("	lista.hover(function(){");
document.writeln("		lista.removeClass(\"now\");");
document.writeln("		$(this).addClass(\"now\");");
document.writeln("		clearTimeout(time);");
document.writeln("		var index = list.find(\"a\").index(this);");
document.writeln("		box.find(\".cont\").hide().eq(index).show();");
document.writeln("		var _height = box.find(\".cont\").eq(index).height()+0;");
document.writeln("		box_show(_height)");
document.writeln("	},function(){");
document.writeln("		time = setTimeout(function(){	");
document.writeln("			box.find(\".cont\").hide();");
document.writeln("			box_hide();");
document.writeln("		},50);");
document.writeln("		lista.removeClass(\"now\");");
document.writeln("		lista.eq(olda).addClass(\"now\");");
document.writeln("	});");
document.writeln("	");
document.writeln("	box.find(\".cont\").hover(function(){");
document.writeln("		var _index = box.find(\".cont\").index(this);");
document.writeln("		lista.removeClass(\"now\");");
document.writeln("		lista.eq(_index).addClass(\"now\");");
document.writeln("		clearTimeout(time);");
document.writeln("		$(this).show();");
document.writeln("		var _height = $(this).height()+0;");
document.writeln("		box_show(_height);");
document.writeln("	},function(){");
document.writeln("		time = setTimeout(function(){		");
document.writeln("			$(this).hide();");
document.writeln("			box_hide();");
document.writeln("		},50);");
document.writeln("		lista.removeClass(\"now\");");
document.writeln("		lista.eq(olda).addClass(\"now\");");
document.writeln("	});");
document.writeln("");
document.writeln("})();");
document.writeln("<\/script>");